// Ajuste aqui: limite de gerações por IP a cada hora e validade das páginas
const LIMITE_POR_HORA = 30;
const VALIDADE_DIAS = 30;

const req = $('Recebe Briefing (POST)').first().json;
const raw = (req.body && typeof req.body === 'object') ? req.body : {};
const usosNaHora = Number(Object.values($input.first().json)[0]) || 0;

const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);

const data = {
  empresa: limpa(raw.empresa, 120),
  segmento: limpa(raw.segmento, 120),
  descricao: limpa(raw.descricao, 1500),
  servicos: limpa(raw.servicos, 1200),
  publico: limpa(raw.publico, 600),
  diferenciais: limpa(raw.diferenciais, 800),
  objetivo: limpa(raw.objetivo, 80) || 'gerar contatos pelo WhatsApp',
  cta: limpa(raw.cta, 60),
  tom: limpa(raw.tom, 60) || 'profissional e próximo',
  cor: limpa(raw.cor, 30) || 'azul',
  cor_hex: /^#[0-9a-f]{6}$/i.test(String(raw.cor_hex || '')) ? String(raw.cor_hex).toLowerCase() : '',
  estilo: limpa(raw.estilo, 40) || 'moderno',
  email: '',
  instagram: limpa(raw.instagram, 60).replace(/^@+/, ''),
  endereco: limpa(raw.endereco, 200),
  horario: limpa(raw.horario, 200),
  depoimentos_reais: limpa(raw.depoimentos, 1500),
  extras: limpa(raw.extras, 1000),
  whatsapp: '',
  whatsapp_link: '',
};

const erros = [];
const obrigatorios = { empresa: 'Nome da empresa', segmento: 'Segmento', descricao: 'Descrição do negócio', servicos: 'Serviços/produtos' };
for (const [campo, rotulo] of Object.entries(obrigatorios)) {
  if (data[campo].length < 2) erros.push(`Preencha o campo "${rotulo}".`);
}

const email = limpa(raw.email, 120);
if (email) {
  if (/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) data.email = email;
  else erros.push('E-mail inválido.');
}

let zap = String(raw.whatsapp || '').replace(/\D/g, '');
if (zap) {
  if (zap.length === 10 || zap.length === 11) zap = '55' + zap;
  if (zap.length >= 12 && zap.length <= 13) {
    data.whatsapp = zap;
    data.whatsapp_link = 'https://wa.me/' + zap;
  } else erros.push('WhatsApp inválido. Use DDD + número, ex: (11) 99999-9999.');
}

let codigo_http = 400;
if (String(raw.website || '').trim()) { erros.push('Requisição recusada.'); }
if (usosNaHora > LIMITE_POR_HORA) { erros.unshift('Muitas páginas geradas nesta rede na última hora. Tente novamente mais tarde.'); codigo_http = 429; }

const slug = (data.empresa || 'pagina').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 40) || 'pagina';
const id = `${slug}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

const base = String(req.webhookUrl || '').split('/webhook/')[0] || 'https://webhookn8n6.inovareinteligenciaartificial.com';
const view = `${base}/webhook/lp-pro-view?id=${id}`;

return [{
  json: {
    valido: erros.length === 0,
    erros,
    codigo_http,
    id,
    slug,
    data,
    criadoEm: new Date().toISOString(),
    urls: { view, download: `${view}&download=1`, statusPath: `/webhook/lp-pro-status?id=${id}` },
    config: { ttl_segundos: VALIDADE_DIAS * 86400 },
  }
}];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const bruto = $input.first().json.output ?? $input.first().json.text ?? '';
const copy = parseJSON(bruto);
const ok = !!(copy && copy.hero && copy.servicos);
const aviso = 'COPY INDISPONIVEL: escreva voce mesmo todos os textos a partir do briefing, seguindo as secoes obrigatorias.';
const reserva = String(bruto).trim() ? { aviso: 'Copy fora do formato JSON: aproveite o texto abaixo.', texto_livre: String(bruto).slice(0, 12000) } : { aviso };
return [{ json: { copy_ok: ok, copy: ok ? copy : reserva } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

const d = $('Normalizar Dados & ID Projeto').first().json.data;
const bruto = $input.first().json.output ?? $input.first().json.text ?? '';
const design = parseJSON(bruto);
const hex = /^#[0-9a-f]{6}$/i;

const reserva = {
  azul: '#2563eb', roxo: '#7c3aed', verde: '#16a34a', vermelho: '#dc2626', laranja: '#ea580c',
  rosa: '#db2777', preto: '#111827', dourado: '#c9a227', turquesa: '#0d9488',
};
const primaria = d.cor_hex || reserva[d.cor] || '#2563eb';
const padrao = {
  conceito: `Visual ${d.estilo} para ${d.segmento}`,
  tema: d.cor === 'preto' || d.estilo === 'elegante' ? 'escuro' : 'claro',
  paleta: { primaria, primaria_escura: primaria, secundaria: '#0f172a', acento: primaria, fundo: '#ffffff', superficie: '#f8fafc', texto: '#0f172a', texto_suave: '#475569', borda: '#e2e8f0' },
  tipografia: { titulos: 'Poppins', corpo: 'Inter', google_fonts_href: 'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Poppins:wght@600;700;800&display=swap' },
};

let final = padrao, ok = false;
if (design && design.paleta && hex.test(design.paleta.primaria || '')) {
  final = design; ok = true;
  if (d.cor_hex) final.paleta.primaria = d.cor_hex;
}
return [{ json: { design_ok: ok, design: final } }];

const d = $('Normalizar Dados & ID Projeto').first().json.data;
const copy = $('Parse Copy').first().json.copy || {};
const seo = copy.seo || {};
const tentativa = $runIndex + 1;
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let html = String($input.first().json.output ?? $input.first().json.text ?? '');
html = html.replace(/^\s*```(?:html)?\s*/i, '').replace(/```\s*$/i, '').trim();
const ini = html.search(/<!doctype html|<html[\s>]/i);
if (ini > 0) html = html.slice(ini);
const fim = html.toLowerCase().lastIndexOf('</html>');
if (fim > -1) html = html.slice(0, fim + 7);

const tem = re => re.test(html);
const problemas = [];
if (!tem(/<\/html>\s*$/i)) problemas.push('HTML cortado antes do </html>');
if (!tem(/<body[\s>]/i)) problemas.push('sem <body>');
if (html.length < 6000) problemas.push(`HTML curto demais (${html.length} caracteres)`);
const completo = problemas.length === 0;
const correcoes = [];

if (!tem(/^<!doctype html>/i)) { html = '<!DOCTYPE html>\n' + html.replace(/^<!doctype[^>]*>/i, ''); correcoes.push('doctype'); }
if (tem(/<html(?![^>]*\blang=)/i)) { html = html.replace(/<html/i, '<html lang="pt-BR"'); correcoes.push('lang'); }
if (!tem(/<head[\s>]/i)) { html = html.replace(/<html[^>]*>/i, m => m + '\n<head></head>'); }

const head = [];
if (!tem(/<meta[^>]+charset/i)) head.push('<meta charset="UTF-8">');
if (!tem(/<meta[^>]+name=["']viewport/i)) head.push('<meta name="viewport" content="width=device-width, initial-scale=1.0">');
if (!tem(/<title>/i)) head.push(`<title>${esc(seo.title || d.empresa)}</title>`);
if (!tem(/<meta[^>]+name=["']description/i)) head.push(`<meta name="description" content="${esc(seo.description || d.descricao.slice(0, 155))}">`);
if (!tem(/property=["']og:title/i)) head.push(`<meta property="og:title" content="${esc(seo.title || d.empresa)}">`, `<meta property="og:description" content="${esc(seo.description || d.descricao.slice(0, 155))}">`, '<meta property="og:type" content="website">');
if (head.length) { html = html.replace(/<head[^>]*>/i, m => m + '\n' + head.join('\n')); correcoes.push('meta tags: ' + head.length); }

if (!completo && tentativa >= 2) {
  if (!tem(/<\/body>/i)) html += '\n</body>';
  if (!tem(/<\/html>/i)) html += '\n</html>';
  correcoes.push('fechamento automático de tags');
}

if (d.whatsapp_link && !/wa\.me\//i.test(html)) {
  const msg = encodeURIComponent(`Olá! Vi o site da ${d.empresa} e gostaria de mais informações.`);
  const botao = `<a href="${d.whatsapp_link}?text=${msg}" target="_blank" rel="noopener" aria-label="Fale conosco no WhatsApp" style="position:fixed;right:20px;bottom:20px;z-index:9999;width:58px;height:58px;border-radius:50%;background:#25d366;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 24px rgba(0,0,0,.25)"><svg width="30" height="30" viewBox="0 0 24 24" fill="#fff" aria-hidden="true"><path d="M20.5 3.5A11.8 11.8 0 0 0 12 0C5.4 0 0 5.4 0 12c0 2.1.6 4.2 1.6 6L0 24l6.2-1.6A12 12 0 0 0 24 12c0-3.2-1.2-6.2-3.5-8.5zM12 21.8c-1.8 0-3.6-.5-5.1-1.4l-.4-.2-3.7 1 1-3.6-.2-.4A9.8 9.8 0 1 1 12 21.8zm5.4-7.3c-.3-.1-1.8-.9-2-1-.3-.1-.5-.1-.7.1l-.9 1.2c-.2.2-.3.2-.6.1-.3-.1-1.3-.5-2.4-1.5-.9-.8-1.5-1.8-1.7-2.1-.2-.3 0-.5.1-.6l.5-.5.3-.5v-.5l-.9-2.2c-.2-.6-.5-.5-.7-.5h-.6c-.2 0-.5.1-.8.4-.3.3-1 1-1 2.5s1.1 2.9 1.2 3.1c.1.2 2.1 3.2 5.1 4.5 2.5 1 3 .8 3.6.7.6-.1 1.8-.7 2-1.4.2-.7.2-1.3.2-1.4-.1-.2-.3-.3-.6-.4z"/></svg></a>`;
  html = /<\/body>/i.test(html) ? html.replace(/<\/body>/i, botao + '\n</body>') : html + botao;
  correcoes.push('botão flutuante de WhatsApp');
}

return [{ json: { html, completo, tentativa, problemas, correcoes, tamanho: html.length, modelo_usado: $('AGENTE 3B — FRONT-END (MODELO RESERVA)').isExecuted ? 'reserva' : 'principal' } }];

const e = $input.first().json.error;
const detalhe = typeof e === 'string' ? e : (e && (e.description || e.message)) || 'Falha desconhecida';
let id = '', empresa = '', criadoEm = '';
try { const n = $('Normalizar Dados & ID Projeto').first().json; id = n.id; empresa = n.data.empresa; criadoEm = n.criadoEm; } catch (x) {}
return [{ json: { id, empresa, criadoEm, status: 'erro', etapa: 0, etapa_falhou: $prevNode.name,
  mensagem: 'A IA não conseguiu concluir a página agora. Tente novamente em alguns minutos.', detalhe: String(detalhe).slice(0, 500),
  atualizadoEm: new Date().toISOString() } }];

const id = String($('Consulta Status (GET)').first().json.query.id || '');
let s = null;
try { s = JSON.parse($('Lê Status (Redis)').first().json.status || 'null'); } catch (e) {}
if (!/^[a-z0-9-]{4,80}$/.test(id) || !s) return [{ json: { status: 'nao_encontrado', mensagem: 'Pedido não encontrado ou expirado.' } }];

const parado = Date.now() - new Date(s.atualizadoEm).getTime();
if (s.status === 'processando' && parado > 20 * 60 * 1000) {
  s.status = 'erro';
  s.mensagem = 'A geração parou de responder. Tente novamente.';
}
delete s.detalhe;
return [{ json: s }];

const q = $('Visualizar Página (GET)').first().json.query || {};
const id = String(q.id || '');
const valido = /^[a-z0-9-]{4,80}$/.test(id);
const html = valido ? $('Lê HTML (Redis)').first().json.html : null;
let st = null;
try { st = valido ? JSON.parse($('Lê Status p/ Viewer (Redis)').first().json.status || 'null') : null; } catch (e) {}

const casca = (titulo, corpo, refresh) => `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">${refresh ? '<meta http-equiv="refresh" content="6">' : ''}<title>${titulo}</title><style>*{box-sizing:border-box;margin:0}body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#07111f;color:#f4f7fb;min-height:100vh;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px}.c{max-width:480px}h1{font-size:28px;margin:18px 0 10px}p{color:#91a4b8;line-height:1.6}a{display:inline-block;margin-top:22px;color:#fff;background:linear-gradient(135deg,#8b5cf6,#6d28d9);padding:12px 22px;border-radius:12px;text-decoration:none;font-weight:600}.s{width:46px;height:46px;border:4px solid rgba(255,255,255,.12);border-top-color:#8b5cf6;border-radius:50%;margin:0 auto;animation:r .8s linear infinite}@keyframes r{to{transform:rotate(360deg)}}.big{font-size:64px;font-weight:800;background:linear-gradient(135deg,#a78bfa,#6d28d9);-webkit-background-clip:text;background-clip:text;color:transparent}</style></head><body><div class="c">${corpo}</div></body></html>`;

if (html) {
  const baixar = q.download === '1';
  const nome = (id.replace(/-[a-z0-9]+$/, '') || 'landing-page') + '.html';
  const tag = `<script src="/webhook/lp-script?id=${id}" defer></script>`;
  const fim = html.toLowerCase().lastIndexOf('</body>');
  const comScript = baixar ? html : (fim > -1 ? html.slice(0, fim) + tag + html.slice(fim) : html + tag);
  return [{ json: { html: comScript, disposicao: baixar ? `attachment; filename="${nome}"` : 'inline', codigo: 200 } }];
}
if (st && st.status === 'processando') {
  const etapas = ['', 'Escrevendo a copy', 'Criando o design', 'Programando a página', 'Publicando'];
  return [{ json: { codigo: 200, disposicao: 'inline', html: casca('Gerando sua página…', `<div class="s"></div><h1>Sua landing page está sendo criada</h1><p>Etapa ${st.etapa} de 4: ${etapas[st.etapa] || ''}. Esta página atualiza sozinha.</p>`, true) } }];
}
if (st && st.status === 'erro') {
  return [{ json: { codigo: 500, disposicao: 'inline', html: casca('Não foi possível gerar', `<div class="big">:(</div><h1>Não conseguimos gerar esta página</h1><p>${st.mensagem}</p><a href="/webhook/lp-pro">Tentar de novo</a>`) } }];
}
return [{ json: { codigo: 404, disposicao: 'inline', html: casca('Página não encontrada', `<div class="big">404</div><h1>Página não encontrada</h1><p>Este link não existe ou expirou.</p><a href="/webhook/lp-pro">Criar uma landing page</a>`) } }];
